      site: {
        workspace: {
          organization: {
            memberships: { some: { userId: user.id } },
          },
        },
      },
    },
    include: {
      site: { select: { name: true, domain: true } },
      findings: {
        include: {
          _count: { select: { occurrences: true } },
        },
        orderBy: { occurrenceCount: "desc" },
        take: 50,
      },
      suggestions: {
        orderBy: { confidence: "desc" },
        take: 10,
      },
    },
  });

  if (!cluster) notFound();

  return (
    <div className="space-y-6">
