        <div className="flex items-center gap-3">
          <span
            className={`badge ${
              cluster.severity === "CRITICAL"
                ? "badge-critical"
                : cluster.severity === "SERIOUS"
                  ? "badge-serious"
                  : cluster.severity === "MODERATE"
                    ? "badge-moderate"
                    : "badge-minor"
