                  </div>
                  <span className="text-xs text-slate-500">
                    {f._count.occurrences} occurrences
                  </span>
                </Link>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

import { requireSession } from '@/lib/session';
import { prisma } from '@/lib/db';
