import { requireSession } from "@/lib/session";
import { prisma } from "@/lib/db";
import Link from "next/link";
import type { Prisma, Severity, FindingStatus, EvidenceSource } from "@aros/db";
import { getRoutePlatformTruth } from "@/lib/platform-truth-cache";
import {
  resolveDashboardOrgMembership,
  runOrgScopedQuery,
} from "@/lib/route-data-boundary";
import { RouteReliabilityNotice } from "@/components/reliability/route-reliability-notice";
import { hasPermission } from "@aros/config";
import { StatusBadge } from "@aros/ui";
import { getAutomationEvidenceFreshnessDescriptor } from "@/lib/findings/evidence-freshness";

type FindingListRow = Prisma.CanonicalFindingGetPayload<{
  include: {
    _count: { select: { occurrences: true } };
    cluster: { select: { id: true; name: true } };
    site: { select: { id: true; name: true; domain: true } };
  };
}>;

export const metadata = { title: "Findings - AROS" };

interface SearchParams {
  page?: string;
  severity?: string;
  status?: string;
  siteId?: string;
  ruleId?: string;
  evidenceSource?: string;
}

export default async function FindingsPage({
  searchParams,
}: {
  searchParams: Promise<SearchParams>;
}) {
  const user = await requireSession();
  const params = await searchParams;
  const platformTruth = await getRoutePlatformTruth();
  const canViewSystem = await prisma.membership
    .findMany({ where: { userId: user.id }, select: { role: true } })
    .then((rows) => rows.some((m) => hasPermission(m.role, "org:system:view")))
    .catch(() => false);

  const orgRes = await resolveDashboardOrgMembership(user.id, platformTruth);

  if (orgRes.kind === "platform_blocked") {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold text-slate-900">Findings</h1>
        <RouteReliabilityNotice
          variant="error"
          title="Findings require a working database"
          showSystemLink={canViewSystem}
        >
          <p>
            Findings cannot be loaded until core data services are healthy. See
            the banner above for status.
          </p>
        </RouteReliabilityNotice>
      </div>
    );
  }

  if (orgRes.kind === "error") {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold text-slate-900">Findings</h1>
        <RouteReliabilityNotice
          variant="error"
          title="Could not verify organization"
          showSystemLink={canViewSystem}
        >
          <p>{orgRes.message}</p>
        </RouteReliabilityNotice>
      </div>
    );
  }

  if (orgRes.kind === "none") {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold text-slate-900">Findings</h1>
        <RouteReliabilityNotice
          variant="info"
          title="No organization membership"
        >
          <p>You need to belong to an organization to view findings.</p>
        </RouteReliabilityNotice>
      </div>
    );
  }

  const page = parseInt(params.page ?? "1", 10);
  const limit = 20;
  const skip = (page - 1) * limit;

  const buildFindingsWhere = (
    organizationId: string,
  ): Prisma.CanonicalFindingWhereInput => {
    const where: Prisma.CanonicalFindingWhereInput = {
      occurrences: {
        some: {
          page: {
            site: { workspace: { organizationId } },
            ...(params.siteId ? { siteId: params.siteId } : {}),
          },
        },
      },
    };

    if (params.severity) {
      where.impact = params.severity as Severity;
    }
    if (params.status) {
      where.status = params.status as FindingStatus;
    }
    if (params.ruleId) {
      where.ruleId = params.ruleId;
    }
    if (
      params.evidenceSource &&
      ["AUTOMATED_AXE", "MANUAL_REVIEW", "IMPORTED"].includes(
        params.evidenceSource,
      )
    ) {
      where.evidenceSource = params.evidenceSource as EvidenceSource;
    }

    return where;
  };

  const listResult = await runOrgScopedQuery(orgRes, async (organizationId) => {
    const where = buildFindingsWhere(organizationId);
    const [findings, total, latestCompletedScan] = await Promise.all([
      prisma.canonicalFinding.findMany({
        where,
        orderBy: [{ impact: "asc" }, { occurrenceCount: "desc" }],
        skip,
        take: limit,
        include: {
          _count: { select: { occurrences: true } },
          cluster: { select: { id: true, name: true } },
          site: { select: { id: true, name: true, domain: true } },
        },
      }),
      prisma.canonicalFinding.count({ where }),
      prisma.scanRun.findFirst({
        where: {
          status: "COMPLETED",
          completedAt: { not: null },
          site: { workspace: { organizationId } },
        },
        orderBy: { completedAt: "desc" },
        select: { completedAt: true },
      }),
    ]);
    return {
      findings,
      total,
      latestCompletedScanCompletedAt: latestCompletedScan?.completedAt ?? null,
    };
  });

  if (!listResult.ok) {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold text-slate-900">Findings</h1>
        <RouteReliabilityNotice
          variant="error"
          title="Findings list unavailable"
          showSystemLink={canViewSystem}
        >
          <p>
            Could not load findings from the database ({listResult.message}).
          </p>
        </RouteReliabilityNotice>
      </div>
    );
  }

  const { findings, total, latestCompletedScanCompletedAt } = listResult.data;
  const totalPages = Math.ceil(total / limit);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Findings</h1>
          <p className="text-slate-500 mt-1">
            {total} deduplicated finding{total === 1 ? "" : "s"} in your
            organization (not a legal conformance score).
          </p>
        </div>
      </div>

      {!platformTruth.flags.jobPipelinesHealthy && (
        <RouteReliabilityNotice
          variant="warning"
          title="Automation freshness is degraded"
          showSystemLink={canViewSystem}
        >
          <p>
            Findings still reflect stored organization data, but workers or
            queues are degraded. Automated evidence freshness is shown as
            degraded until pipelines recover.
          </p>
        </RouteReliabilityNotice>
      )}

      <div className="card">
        <form className="flex flex-wrap gap-4" method="GET">
          <div>
            <label htmlFor="severity-filter" className="label">
              Severity
            </label>
            <select
              id="severity-filter"
              name="severity"
              className="input"
              defaultValue={params.severity ?? ""}
            >
              <option value="">All</option>
              <option value="CRITICAL">Critical</option>
              <option value="SERIOUS">Serious</option>
              <option value="MODERATE">Moderate</option>
              <option value="MINOR">Minor</option>
            </select>
          </div>
          <div>
            <label htmlFor="status-filter" className="label">
              Status
            </label>
            <select
              id="status-filter"
              name="status"
              className="input"
              defaultValue={params.status ?? ""}
            >
              <option value="">All</option>
              <option value="OPEN">Open</option>
              <option value="ACKNOWLEDGED">Acknowledged</option>
              <option value="IN_PROGRESS">In progress</option>
              <option value="RESOLVED">Resolved</option>
              <option value="MITIGATED">Mitigated</option>
              <option value="FALSE_POSITIVE">False positive</option>
              <option value="WONT_FIX">Won&apos;t fix / accepted risk</option>
            </select>
          </div>
          <div>
            <label htmlFor="source-filter" className="label">
              Evidence source
            </label>
            <select
              id="source-filter"
              name="evidenceSource"
              className="input"
              defaultValue={params.evidenceSource ?? ""}
            >
              <option value="">All</option>
              <option value="AUTOMATED_AXE">Automated (axe)</option>
              <option value="MANUAL_REVIEW">Manual review</option>
              <option value="IMPORTED">Imported</option>
            </select>
          </div>
          <div className="flex items-end">
            <button type="submit" className="btn-secondary">
              Filter
            </button>
          </div>
        </form>
      </div>

      {findings.length === 0 ? (
        <div className="card text-center py-12 space-y-2">
          <p className="text-slate-700 font-medium">
            No findings match your filters
          </p>
          <p className="text-sm text-slate-500">
            {total === 0
              ? "There are no findings for this organization yet, or none match the selected filters."
              : "Try clearing filters or changing the page."}
          </p>
        </div>
      ) : (
        <div className="space-y-3">
          {findings.map((finding) => (
            <FindingRow
              key={finding.id}
              finding={finding}
              latestCompletedScanCompletedAt={latestCompletedScanCompletedAt}
              jobPipelinesHealthy={platformTruth.flags.jobPipelinesHealthy}
            />
          ))}
        </div>
      )}

      {totalPages > 1 && (
        <nav
          className="flex items-center justify-center gap-2"
          aria-label="Pagination"
        >
          {page > 1 && (
            <Link
              href={`/findings?page=${page - 1}&severity=${params.severity ?? ""}&status=${params.status ?? ""}&evidenceSource=${params.evidenceSource ?? ""}`}
              className="btn-secondary text-sm"
              aria-label={`Previous page, page ${page - 1} of ${totalPages}`}
            >
              Previous
            </Link>
          )}
          <span className="text-sm text-slate-500" aria-current="page">
            Page {page} of {totalPages}
          </span>
          {page < totalPages && (
            <Link
              href={`/findings?page=${page + 1}&severity=${params.severity ?? ""}&status=${params.status ?? ""}&evidenceSource=${params.evidenceSource ?? ""}`}
              className="btn-secondary text-sm"
              aria-label={`Next page, page ${page + 1} of ${totalPages}`}
            >
              Next
            </Link>
          )}
        </nav>
      )}
    </div>
  );
}

function FindingRow({
  finding,
  latestCompletedScanCompletedAt,
  jobPipelinesHealthy,
}: {
  finding: FindingListRow;
  latestCompletedScanCompletedAt: Date | null;
  jobPipelinesHealthy: boolean;
}) {
  const freshness = getAutomationEvidenceFreshnessDescriptor({
    evidenceSource: finding.evidenceSource,
    lastVerifiedAt: finding.lastVerifiedAt,
    latestCompletedScanCompletedAt,
    jobPipelinesHealthy,
  });

  const freshnessToneClass =
    freshness?.tone === "warning"
      ? "bg-amber-50 text-amber-700 border border-amber-200"
      : "bg-slate-100 text-slate-700 border border-slate-200";

  return (
    <Link
      href={`/findings/${finding.id}`}
      className="card hover:shadow-md transition-shadow block"
    >
      <div className="flex items-start justify-between">
        <div className="flex-1">
          <div className="flex items-center gap-2 mb-1">
            <span
              className={`badge ${
                finding.impact === "CRITICAL"
                  ? "badge-critical"
                  : finding.impact === "SERIOUS"
                    ? "badge-serious"
                    : finding.impact === "MODERATE"
                      ? "badge-moderate"
                      : "badge-minor"
              }`}
            >
              {finding.impact.toLowerCase()}
            </span>
            <span className="text-xs text-slate-400">{finding.ruleId}</span>
            <EvidenceSourceBadge source={finding.evidenceSource} />
            {freshness && freshness.freshness !== "current" && (
              <span
                className={`badge ${freshnessToneClass}`}
                title={freshness.detail}
                aria-label={`Automation evidence freshness: ${freshness.badgeLabel}. ${freshness.detail}`}
              >
                {freshness.badgeLabel}
              </span>
            )}
            {finding.cluster && (
              <span className="badge bg-purple-100 text-purple-800">
                {finding.cluster.name}
              </span>
            )}
          </div>
          <p className="text-sm font-medium text-slate-900">
            {finding.description}
          </p>
          <div className="flex items-center gap-4 mt-2 text-xs text-slate-500">
            <span>{finding._count.occurrences} occurrences</span>
            <span>Site: {finding.site.name}</span>
            <span>First seen: {finding.firstSeenAt.toLocaleDateString()}</span>
            {finding.lastVerifiedAt && (
              <span>
                Last verified: {finding.lastVerifiedAt.toLocaleDateString()}
              </span>
            )}
            {finding.wcagTags.length > 0 && (
              <span>WCAG: {finding.wcagTags.join(", ")}</span>
            )}
          </div>
        </div>
        <div>
          <StatusBadge status={finding.status} />
        </div>
      </div>
    </Link>
  );
}

function EvidenceSourceBadge({ source }: { source: string }) {
  const label =
    source === "AUTOMATED_AXE"
      ? "Automated"
      : source === "MANUAL_REVIEW"
        ? "Manual"
        : source === "IMPORTED"
          ? "Imported"
          : source;
  return (
    <span
      className="text-xs rounded px-1.5 py-0.5 bg-slate-100 text-slate-600"
      title="How this finding entered the system"
    >
      {label}
    </span>
  );
}

import { redirect } from "next/navigation";
import { cookies } from "next/headers";
import { getSession } from "@/lib/session";
import { prisma } from "@/lib/db";
import { Sidebar } from "@/components/layout/sidebar";
import { TopBar } from "@/components/layout/top-bar";
import { DashboardNavProvider } from "@/components/layout/dashboard-nav-context";
import { MobileDashboardNav } from "@/components/layout/mobile-dashboard-nav";
import { hasPermission } from "@aros/config";
import type { Prisma } from "@aros/db";
import { getRoutePlatformTruth } from "@/lib/platform-truth-cache";
import { PlatformShellBanner } from "@/components/reliability/platform-shell-banner";
import { RouteReliabilityNotice } from "@/components/reliability/route-reliability-notice";

const membershipLayoutInclude = {
  organization: {
    include: {
      workspaces: { select: { id: true, name: true, slug: true } },
      subscription: {
        select: {
          aiEnabled: true,
          aiTokenLimit: true,
        },
      },
    },
  },
} satisfies Prisma.MembershipInclude;

type LayoutMembership = Prisma.MembershipGetPayload<{
  include: typeof membershipLayoutInclude;
}>;

export default async function DashboardLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const user = await getSession();
  if (!user) redirect("/login");

  let memberships: LayoutMembership[] = [];
  let layoutDbError: string | null = null;
  try {
    memberships = await prisma.membership.findMany({
      where: { userId: user.id },
      include: membershipLayoutInclude,
    });
  } catch (e) {
    layoutDbError = e instanceof Error ? e.message : "Database error";
    console.error("[dashboard layout] membership load failed", e);
  }

  const orgs = memberships.map((m) => ({
    id: m.organization.id,
    name: m.organization.name,
    slug: m.organization.slug,
    role: m.role,
    workspaces: m.organization.workspaces,
    subscription: m.organization.subscription,
  }));

  const cookieStore = await cookies();
  const preferredOrgId = cookieStore.get("aros_active_org")?.value;
  const activeOrgId =
    preferredOrgId && orgs.some((o) => o.id === preferredOrgId)
      ? preferredOrgId
      : orgs[0]?.id;

  const canViewSystem = memberships.some((m) =>
    hasPermission(m.role, "org:system:view"),
  );

  let platformTruth: Awaited<ReturnType<typeof getRoutePlatformTruth>> | null =
    null;
  try {
    platformTruth = await getRoutePlatformTruth();
  } catch (e) {
    console.error("[dashboard layout] platform truth failed", e);
  }

  const shellAudience = canViewSystem ? "operator" : "user";

  const activeOrg = orgs.find((o) => o.id === activeOrgId);
  let aiUsage = undefined;
  if (activeOrg) {
    const usage = await prisma.aiUsageLog.aggregate({
      where: { organizationId: activeOrg.id },
      _sum: { totalTokens: true },
    });
    aiUsage = {
      enabled: activeOrg.subscription?.aiEnabled ?? false,
      limit: activeOrg.subscription?.aiTokenLimit ?? 0,
      used: usage._sum.totalTokens ?? 0,
    };
  }

  return (
    <DashboardNavProvider>
      <a
        href="#main-content"
        className="sr-only focus:not-sr-only focus:absolute focus:top-2 focus:left-2 focus:z-[9999] focus:rounded focus:bg-brand-600 focus:px-4 focus:py-2 focus:text-white focus:outline-none focus:ring-2 focus:ring-brand-400"
      >
        Skip to main content
      </a>
      <div className="flex min-h-dvh overflow-hidden bg-slate-50 md:h-screen">
        <Sidebar
          orgs={orgs}
          user={user}
          canViewSystem={canViewSystem}
          activeOrgId={activeOrgId}
          aiUsage={aiUsage}
        />
        <MobileDashboardNav
          orgs={orgs}
          user={user}
          canViewSystem={canViewSystem}
          activeOrgId={activeOrgId}
          aiUsage={aiUsage}
        />
        <div className="flex min-h-0 flex-1 flex-col overflow-hidden">
          <TopBar
            user={user}
            platformTruth={platformTruth}
            canViewSystem={canViewSystem}
          />
          {platformTruth && (
            <PlatformShellBanner
              truth={platformTruth}
              audience={shellAudience}
              canViewSystem={canViewSystem}
            />
          )}
          <main
            id="main-content"
            className="flex-1 overflow-y-auto p-4 pb-[max(1.5rem,env(safe-area-inset-bottom))] pt-4 md:p-6"
          >
            {layoutDbError && (
              <RouteReliabilityNotice
                variant="error"
                title="Navigation data unavailable"
                showSystemLink={canViewSystem}
              >
                <p>
                  Organization and workspace lists could not be loaded (
                  {layoutDbError}). Pages that need organization context may not
                  work until the database is reachable.
                </p>
              </RouteReliabilityNotice>
            )}
            {!layoutDbError && memberships.length === 0 && (
              <RouteReliabilityNotice
                variant="info"
                title="No organization membership"
              >
                <p>
                  You are signed in but not assigned to an organization. Ask an
                  administrator to invite you, or contact support if you believe
                  this is a mistake.
                </p>
              </RouteReliabilityNotice>
            )}
            {children}
          </main>
        </div>
      </div>
    </DashboardNavProvider>
  );
}

"use server";

import { redirect } from "next/navigation";
import { requireSession } from "@/lib/session";
import { prisma } from "@/lib/db";
import { hasPermission } from "@aros/config";

async function requireSuggestionAccess(suggestionId: string, userId: string) {
  if (!suggestionId) {
    redirect("/remediation?error=missing_id");
  }

  const suggestion = await prisma.remediationSuggestion.findUnique({
    where: { id: suggestionId },
    select: {
      id: true,
      status: true,
      finding: {
        select: {
          site: {
            select: {
              workspace: {
                select: {
                  organizationId: true,
                  organization: {
                    select: {
                      memberships: {
                        where: { userId },
                        take: 1,
                        select: { role: true },
                      },
                    },
                  },
                },
              },
            },
          },
        },
      },
      cluster: {
        select: {
          site: {
            select: {
              workspace: {
                select: {
                  organizationId: true,
                  organization: {
                    select: {
                      memberships: {
                        where: { userId },
                        take: 1,
                        select: { role: true },
                      },
                    },
                  },
                },
              },
            },
          },
        },
      },
    },
  });

  if (!suggestion) {
    redirect("/remediation?error=not_found");
  }

  const orgMembership =
    suggestion.finding?.site.workspace.organization.memberships[0] ??
    suggestion.cluster?.site.workspace.organization.memberships[0];

  if (!orgMembership) {
    redirect("/remediation?error=forbidden");
  }

  return { suggestion, role: orgMembership.role };
}

export async function approveSuggestionAction(formData: FormData) {
  const user = await requireSession();
  const suggestionId = (formData.get("suggestionId") as string) || "";

  const { suggestion, role } = await requireSuggestionAccess(
    suggestionId,
    user.id,
  );

  if (!hasPermission(role, "suggestions:approve")) {
    redirect(`/remediation/${suggestionId}?error=forbidden`);
  }

  if (suggestion.status !== "DRAFT" && suggestion.status !== "VALIDATED") {
    redirect(`/remediation/${suggestionId}?error=invalid_transition`);
  }

  try {
    await prisma.remediationSuggestion.update({
      where: { id: suggestionId },
      data: {
        status: "APPROVED",
        appliedBy: user.id,
        appliedAt: new Date(),
      },
    });
  } catch {
    redirect(`/remediation/${suggestionId}?error=update_failed`);
  }

  redirect(`/remediation/${suggestionId}`);
}

export async function rejectSuggestionAction(formData: FormData) {
  const user = await requireSession();
  const suggestionId = (formData.get("suggestionId") as string) || "";

  const { suggestion, role } = await requireSuggestionAccess(
    suggestionId,
    user.id,
  );

  if (!hasPermission(role, "suggestions:approve")) {
    redirect(`/remediation/${suggestionId}?error=forbidden`);
  }

  if (suggestion.status === "REJECTED" || suggestion.status === "APPLIED") {
    redirect(`/remediation/${suggestionId}?error=invalid_transition`);
  }

  try {
    await prisma.remediationSuggestion.update({
      where: { id: suggestionId },
      data: { status: "REJECTED" },
    });
  } catch {
    redirect(`/remediation/${suggestionId}?error=update_failed`);
  }

  redirect(`/remediation/${suggestionId}`);
}

export async function exportSnippetAction(formData: FormData) {
  const user = await requireSession();
  const suggestionId = (formData.get("suggestionId") as string) || "";

  const { suggestion, role } = await requireSuggestionAccess(
    suggestionId,
    user.id,
  );

  if (!hasPermission(role, "suggestions:export")) {
    redirect(`/remediation/${suggestionId}?error=forbidden`);
  }

  if (suggestion.status !== "APPROVED" && suggestion.status !== "VALIDATED") {
    redirect(`/remediation/${suggestionId}?error=invalid_transition`);
  }

  try {
    await prisma.remediationSuggestion.update({
      where: { id: suggestionId },
      data: { status: "EXPORTED" },
    });
  } catch {
    redirect(`/remediation/${suggestionId}?error=update_failed`);
  }

  redirect(`/remediation/${suggestionId}`);
}

import { notFound } from "next/navigation";
import { requireSession } from "@/lib/session";
import { prisma } from "@/lib/db";
import Link from "next/link";
import {
  approveSuggestionAction,
  rejectSuggestionAction,
  exportSnippetAction,
} from "./actions";
import { StatusBadge } from "@aros/ui";
import { RouteReliabilityNotice } from "@/components/reliability/route-reliability-notice";
import { hasPermission } from "@aros/config";
import { getRoutePlatformTruth } from "@/lib/platform-truth-cache";
import { resolveDashboardOrgMembership } from "@/lib/route-data-boundary";
import { sanitizeAiCode } from "@/lib/sanitizer";
import { AiUpsell } from "@/components/monetization/ai-upsell";


export default async function SuggestionDetailPage({
  params,
  searchParams,
}: {
  params: Promise<{ suggestionId: string }>;
  searchParams: Promise<{ error?: string }>;
}) {
  const { suggestionId } = await params;
  const sp = await searchParams;
  const user = await requireSession();
  const platformTruth = await getRoutePlatformTruth();
  const orgRes = await resolveDashboardOrgMembership(user.id, platformTruth);

  if (orgRes.kind !== "ok") {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold text-slate-900">
          Remediation Suggestion
        </h1>
        <RouteReliabilityNotice variant="error" title="Cannot load suggestion">
          <p>Organization context unavailable.</p>
        </RouteReliabilityNotice>
      </div>
    );
  }

  const suggestion = await prisma.remediationSuggestion.findFirst({
    where: {
      id: suggestionId,
      OR: [
        {
          finding: {
            occurrences: {
              some: {
                page: {
                  site: {
                    workspace: { organizationId: orgRes.organizationId },
                  },
                },
              },
            },
          },
        },
        {
          cluster: {
            site: { workspace: { organizationId: orgRes.organizationId } },
          },
        },
      ],
    },
    include: {
      reviewTask: true,
      finding: {
        include: {
          occurrences: {
            take: 1,
            include: {
              page: {
                include: { site: true },
              },
            },
          },
          _count: { select: { occurrences: true } },
        },
      },
      cluster: {
        include: {
          site: true,
        },
      },
    },
  });


  if (!suggestion) notFound();

  const canApprove = hasPermission(orgRes.role, "suggestions:approve");
  const canExport = hasPermission(orgRes.role, "suggestions:export");

  const errorMessage = sp.error
    ? ({
        forbidden: "You do not have permission for that action.",
        invalid_transition: "That action is not valid from the current status.",
        update_failed: "Update failed. Please try again.",
      }[sp.error] ?? "An error occurred.")
    : null;

  const subscription = await prisma.subscription.findUnique({
    where: { organizationId: orgRes.organizationId },
  });

  const occurrence = suggestion.finding?.occurrences[0];
  const page = occurrence?.page;
  const site = page?.site || suggestion.cluster?.site;

  if (!site) {
    notFound();
  }

  return (
    <div className="space-y-6">
      <div>
        <div className="flex items-center gap-2 text-sm text-slate-500 mb-1">
          <Link
            href="/remediation"
            className="hover:text-brand-600 focus-visible:outline-brand-600 rounded px-1 -mx-1"
          >
            Remediation
          </Link>
          <span>/</span>
        </div>
        <h1 className="text-2xl font-bold text-slate-900">
          Remediation Suggestion
        </h1>
      </div>

      {errorMessage && (
        <RouteReliabilityNotice variant="error" title="Action not applied">
          <p>{errorMessage}</p>
        </RouteReliabilityNotice>
      )}

      <div className="card">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <span className="badge bg-blue-100 text-blue-800">
              {suggestion.type.toLowerCase().replace("_", " ")}
            </span>
            <StatusBadge status={suggestion.status} />
          </div>
          <p className="text-sm text-slate-500">
            Confidence:{" "}
            <strong>{Math.round(suggestion.confidence * 100)}%</strong>
          </p>
        </div>

        <h2 className="text-sm font-medium text-slate-500 mb-2">Rationale</h2>
        <p className="text-sm text-slate-700">{suggestion.rationale}</p>

        {suggestion.finding && (
          <div className="mt-4 pt-4 border-t border-slate-200">
            <p className="text-xs text-slate-500">Related finding:</p>
            <Link
              href={`/findings/${suggestion.finding.id}`}
              className="text-sm text-brand-600 hover:underline"
            >
              {suggestion.finding.description}
            </Link>
            <span className="text-xs text-slate-400 ml-2">
              ({suggestion.finding._count.occurrences} occurrences)
            </span>
          </div>
        )}

        {suggestion.cluster && (
          <div className="mt-3 pt-3 border-t border-slate-200">
            <p className="text-xs text-slate-500">Component cluster:</p>
            <Link
              href={`/clusters/${suggestion.cluster.id}`}
              className="text-sm text-brand-600 hover:underline"
            >
              {suggestion.cluster.name}
            </Link>
            <span className="text-xs text-slate-400 ml-2">
              ({suggestion.cluster.pageCount} pages)
            </span>
          </div>
        )}
      </div>

      <div className="card">
        <h2 className="text-lg font-semibold text-slate-900 mb-4">
          Code Changes
        </h2>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          <div>
            <h3 className="text-sm font-medium text-red-700 mb-2">
              Original Code
            </h3>
            <pre className="bg-red-50 border border-red-200 rounded-lg p-4 text-sm overflow-x-auto max-h-[400px] whitespace-pre-wrap">
              <code>{suggestion.originalCode}</code>
            </pre>
          </div>
          <div>
            <h3 className="text-sm font-medium text-green-700 mb-2">
              Suggested Fix
            </h3>
            <pre className="bg-green-50 border border-green-200 rounded-lg p-4 text-sm overflow-x-auto max-h-[400px] whitespace-pre-wrap">
              <code>{sanitizeAiCode(suggestion.suggestedCode)}</code>
            </pre>
          </div>
        </div>
      </div>


      {suggestion.validationResult && (
        <div className="card">
          <h2 className="text-lg font-semibold text-slate-900 mb-2">
            Validation Result
          </h2>
          <pre className="bg-slate-50 rounded-lg p-3 text-sm overflow-x-auto">
            {JSON.stringify(suggestion.validationResult, null, 2)}
          </pre>
        </div>
      )}

      {(() => {
        if (!subscription?.aiEnabled) {
          return <AiUpsell reason={subscription ? "tier_limit" : "disabled"} />;
        }

        // Final gate for approval
        if (!(canApprove || canExport)) return null;

        return (
          <div className="card">
            <h2 className="text-lg font-semibold text-slate-900 mb-4">Actions</h2>
            <div className="flex flex-wrap gap-3">
              {canApprove &&
                (suggestion.status === "DRAFT" ||
                  suggestion.status === "VALIDATED") && (
                  <form action={approveSuggestionAction}>
                    <input
                      type="hidden"
                      name="suggestionId"
                      value={suggestionId}
                    />
                    <button type="submit" className="btn-primary">
                      Approve Suggestion
                    </button>
                  </form>
                )}

              {canApprove &&
                suggestion.status !== "REJECTED" &&
                suggestion.status !== "APPLIED" && (
                  <form action={rejectSuggestionAction}>
                    <input
                      type="hidden"
                      name="suggestionId"
                      value={suggestionId}
                    />
                    <button type="submit" className="btn-danger">
                      Reject
                    </button>
                  </form>
                )}

              {canExport &&
                (suggestion.status === "APPROVED" ||
                  suggestion.status === "VALIDATED") && (
                  <form action={exportSnippetAction}>
                    <input
                      type="hidden"
                      name="suggestionId"
                      value={suggestionId}
                    />
                    <button type="submit" className="btn-secondary">
                      Export as Snippet
                    </button>
                  </form>
                )}
            </div>
          </div>
        );
      })()}

    </div>
  );
}

import { requireSession } from "@/lib/session";
import { prisma } from "@/lib/db";
import Link from "next/link";
import { getRoutePlatformTruth } from "@/lib/platform-truth-cache";
import {
  resolveDashboardOrgMembership,
  runOrgScopedQuery,
} from "@/lib/route-data-boundary";
import { RouteReliabilityNotice } from "@/components/reliability/route-reliability-notice";
import { hasPermission } from "@aros/config";
import { StatusBadge } from "@aros/ui";

export const metadata = { title: "Remediation - AROS" };

export default async function RemediationPage() {
  const user = await requireSession();
  const platformTruth = await getRoutePlatformTruth();
  const canViewSystem = await prisma.membership
    .findMany({ where: { userId: user.id }, select: { role: true } })
    .then((rows) => rows.some((m) => hasPermission(m.role, "org:system:view")))
    .catch(() => false);

  const orgRes = await resolveDashboardOrgMembership(user.id, platformTruth);

  if (orgRes.kind === "platform_blocked") {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold text-slate-900">
          Remediation Suggestions
        </h1>
        <RouteReliabilityNotice
          variant="error"
          title="Remediation data requires a working database"
          showSystemLink={canViewSystem}
        >
          <p>
            Suggestions cannot be loaded until core data services are healthy.
          </p>
        </RouteReliabilityNotice>
      </div>
    );
  }

  if (orgRes.kind === "error") {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold text-slate-900">
          Remediation Suggestions
        </h1>
        <RouteReliabilityNotice
          variant="error"
          title="Could not verify organization"
          showSystemLink={canViewSystem}
        >
          <p>{orgRes.message}</p>
        </RouteReliabilityNotice>
      </div>
    );
  }

  if (orgRes.kind === "none") {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold text-slate-900">
          Remediation Suggestions
        </h1>
        <RouteReliabilityNotice
          variant="info"
          title="No organization membership"
        >
          <p>You need an organization to view remediation suggestions.</p>
        </RouteReliabilityNotice>
      </div>
    );
  }

  const suggestionsResult = await runOrgScopedQuery(orgRes, (orgId) =>
    prisma.remediationSuggestion.findMany({
      where: {
        OR: [
          {
            finding: {
              occurrences: {
                some: {
                  page: { site: { workspace: { organizationId: orgId } } },
                },
              },
            },
          },
          {
            cluster: { site: { workspace: { organizationId: orgId } } },
          },
        ],
      },
      orderBy: [{ status: "asc" }, { confidence: "desc" }],
      include: {
        finding: { select: { description: true, ruleId: true, impact: true } },
        cluster: { select: { name: true } },
      },
      take: 50,
    }),
  );

  if (!suggestionsResult.ok) {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold text-slate-900">
          Remediation Suggestions
        </h1>
        <RouteReliabilityNotice
          variant="error"
          title="Could not load suggestions"
          showSystemLink={canViewSystem}
        >
          <p>{suggestionsResult.message}</p>
        </RouteReliabilityNotice>
      </div>
    );
  }

  const suggestions = suggestionsResult.data;

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-slate-900">
          Remediation Suggestions
        </h1>
        <p className="text-slate-500 mt-1">
          AI-generated fix suggestions. Review before applying.
        </p>
      </div>

      <div className="bg-amber-50 border border-amber-200 rounded-lg p-4 text-sm text-amber-800">
        All suggestions are AI-generated drafts. They must be reviewed by a
        human before export or application. Automated scanning cannot guarantee
        full WCAG conformance.
      </div>

      {suggestions.length === 0 ? (
        <div className="card text-center py-12">
          <p className="text-slate-500">
            No remediation suggestions yet. Run scans to generate them.
          </p>
        </div>
      ) : (
        <div className="space-y-3">
          {suggestions.map((s) => (
            <Link
              key={s.id}
              href={`/remediation/${s.id}`}
              className="card hover:shadow-md transition-shadow block"
            >
              <div className="flex items-start justify-between">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <span className="badge bg-blue-100 text-blue-800">
                      {s.type.toLowerCase().replace("_", " ")}
                    </span>
                    <StatusBadge status={s.status} />
                    {s.cluster && (
                      <span className="text-xs text-purple-600">
                        {s.cluster.name}
                      </span>
                    )}
                  </div>
                  <p className="text-sm font-medium text-slate-900">
                    {s.finding?.description ?? s.rationale.slice(0, 100)}
                  </p>
                  <p className="text-xs text-slate-500 mt-1 line-clamp-2">
                    {s.rationale}
                  </p>
                </div>
                <div className="text-right">
                  <p className="text-sm font-medium text-slate-900">
                    {Math.round(s.confidence * 100)}%
                  </p>
                  <p className="text-xs text-slate-500">confidence</p>
                </div>
              </div>
            </Link>
          ))}
        </div>
      )}
    </div>
  );
}

import { requireSession } from "@/lib/session";
import { prisma } from "@/lib/db";
import { generateReportAction } from "./actions";
import { getRoutePlatformTruth } from "@/lib/platform-truth-cache";
import {
  resolveDashboardOrgMembership,
  runOrgScopedQuery,
} from "@/lib/route-data-boundary";
import { RouteReliabilityNotice } from "@/components/reliability/route-reliability-notice";
import { hasPermission } from "@aros/config";
import { buildFindingsOperationalSummary } from "@/lib/findings/reporting-summary";

export const metadata = { title: "Reports - AROS" };

export default async function ReportsPage({
  searchParams,
}: {
  searchParams: Promise<{ report_error?: string }>;
}) {
  const user = await requireSession();
  const platformTruth = await getRoutePlatformTruth();
  const params = await searchParams;
  const canViewSystem = await prisma.membership
    .findMany({ where: { userId: user.id }, select: { role: true } })
    .then((rows) => rows.some((m) => hasPermission(m.role, "org:system:view")))
    .catch(() => false);

  const reportError =
    params.report_error === "no_org"
      ? "Could not determine your organization. Please try again."
      : params.report_error === "query_failed"
        ? "Report query failed. Please try again or contact support."
        : null;

  const orgRes = await resolveDashboardOrgMembership(user.id, platformTruth);

  if (orgRes.kind === "platform_blocked") {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold text-slate-900">Evidence Reports</h1>
        <RouteReliabilityNotice
          variant="error"
          title="Reports require a working database"
          showSystemLink={canViewSystem}
        >
          <p>
            Report data cannot be loaded until core data services are healthy.
          </p>
        </RouteReliabilityNotice>
      </div>
    );
  }

  if (orgRes.kind === "error") {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold text-slate-900">Evidence Reports</h1>
        <RouteReliabilityNotice
          variant="error"
          title="Could not verify organization"
          showSystemLink={canViewSystem}
        >
          <p>{orgRes.message}</p>
        </RouteReliabilityNotice>
      </div>
    );
  }

  if (orgRes.kind === "none") {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold text-slate-900">Evidence Reports</h1>
        <RouteReliabilityNotice
          variant="info"
          title="No organization membership"
        >
          <p>You need an organization to generate reports.</p>
        </RouteReliabilityNotice>
      </div>
    );
  }

  const statsResult = await runOrgScopedQuery(orgRes, async (orgId) => {
    const [sites, opSummary] = await Promise.all([
      prisma.site.findMany({
        where: { workspace: { organizationId: orgId } },
        select: { id: true, name: true, domain: true },
      }),
      buildFindingsOperationalSummary(
        prisma,
        orgId,
        platformTruth.flags.jobPipelinesHealthy,
      ),
    ]);
    return { opSummary, sites };
  });

  if (!statsResult.ok) {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold text-slate-900">Evidence Reports</h1>
        <RouteReliabilityNotice
          variant="error"
          title="Could not load report summary"
          showSystemLink={canViewSystem}
        >
          <p>{statsResult.message}</p>
        </RouteReliabilityNotice>
      </div>
    );
  }

  const { opSummary, sites } = statsResult.data;

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-slate-900">Evidence Reports</h1>
        <p className="text-slate-500 mt-1">
          Generate conformance evidence and status reports.
        </p>
      </div>

      {reportError && (
        <RouteReliabilityNotice
          variant="error"
          title="Report generation failed"
        >
          <p>{reportError}</p>
        </RouteReliabilityNotice>
      )}

      <div className="bg-amber-50 border border-amber-200 rounded-lg p-4 text-sm text-amber-800">
        Reports generated by this platform provide evidence of testing and
        remediation efforts. They do not constitute a legal guarantee of WCAG
        conformance. Full conformance requires manual expert review of criteria
        that cannot be automated.
      </div>

      {!platformTruth.flags.jobPipelinesHealthy && (
        <RouteReliabilityNotice
          variant="warning"
          title="Background pipelines degraded"
          showSystemLink={canViewSystem}
        >
          <p>
            Scan queues or workers may be unavailable. Counts below still
            reflect stored data; automated evidence may be stale until pipelines
            recover.
          </p>
        </RouteReliabilityNotice>
      )}

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="card">
          <p className="text-sm text-slate-500">Total findings (org)</p>
          <p className="text-2xl font-bold text-slate-900">
            {opSummary.totals.findings}
          </p>
        </div>
        <div className="card">
          <p className="text-sm text-slate-500">Open</p>
          <p className="text-2xl font-bold text-red-600">
            {opSummary.totals.open}
          </p>
        </div>
        <div className="card">
          <p className="text-sm text-slate-500">Resolved</p>
          <p className="text-2xl font-bold text-green-600">
            {opSummary.totals.resolved}
          </p>
        </div>
        <div className="card">
          <p className="text-sm text-slate-500">Critical open</p>
          <p className="text-2xl font-bold text-red-700">
            {opSummary.totals.criticalOpen}
          </p>
        </div>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="card">
          <p className="text-sm text-slate-500">Acknowledged</p>
          <p className="text-2xl font-bold text-slate-900">
            {opSummary.totals.acknowledged}
          </p>
        </div>
        <div className="card">
          <p className="text-sm text-slate-500">In progress</p>
          <p className="text-2xl font-bold text-blue-600">
            {opSummary.totals.inProgress}
          </p>
        </div>
        <div className="card">
          <p className="text-sm text-slate-500">Mitigated</p>
          <p className="text-2xl font-bold text-emerald-700">
            {opSummary.totals.mitigated}
          </p>
        </div>
        <div className="card">
          <p className="text-sm text-slate-500">Stale automated evidence</p>
          <p className="text-2xl font-bold text-amber-700">
            {opSummary.staleAutomationCount}
          </p>
        </div>
      </div>

      <div className="card text-sm text-slate-600 space-y-2">
        <p className="font-medium text-slate-900">Evidence source mix</p>
        <p>
          Automated (axe): {opSummary.evidenceSourceMix.automatedAxe} ┬╖ Manual
          review: {opSummary.evidenceSourceMix.manualReview} ┬╖ Imported:{" "}
          {opSummary.evidenceSourceMix.imported}
        </p>
        <p className="text-slate-500">{opSummary.automationFreshnessNote}</p>
      </div>

      <div className="card">
        <h2 className="text-lg font-semibold text-slate-900 mb-4">
          Generate Report
        </h2>
        <form action={generateReportAction} className="space-y-4">
          <div>
            <label htmlFor="report-site" className="label">
              Site
            </label>
            <select id="report-site" name="siteId" className="input">
              <option value="">All sites</option>
              {sites.map((site) => (
                <option key={site.id} value={site.id}>
                  {site.name} ({site.domain})
                </option>
              ))}
            </select>
          </div>
          <div>
            <label htmlFor="report-format" className="label">
              Format
            </label>
            <select id="report-format" name="format" className="input">
              <option value="json">JSON</option>
              <option value="csv">CSV</option>
            </select>
          </div>
          <button type="submit" className="btn-primary">
            Generate Report
          </button>
        </form>
      </div>
    </div>
  );
}

"use server";

import { redirect } from "next/navigation";
import { revalidatePath } from "next/cache";
import { requireSession } from "@/lib/session";
import { prisma } from "@/lib/db";
import type { ReviewStatus } from "@aros/db";
import { hasPermission } from "@aros/config";

const VALID_REVIEW_STATUSES: ReviewStatus[] = [
  "PENDING",
  "IN_PROGRESS",
  "APPROVED",
  "REJECTED",
  "NEEDS_CHANGES",
];

export async function updateReviewAction(formData: FormData) {
  const user = await requireSession();
  const taskId = formData.get("taskId") as string;
  const status = (formData.get("status") as string) || "";

  if (!taskId) {
    redirect("/reviews?review_error=missing_task");
  }

  if (!VALID_REVIEW_STATUSES.includes(status as ReviewStatus)) {
    redirect("/reviews?review_error=invalid_status");
  }

  const reviewStatus = status as ReviewStatus;

  const task = await prisma.reviewTask.findUnique({
    where: { id: taskId },
    select: {
      id: true,
      status: true,
      suggestion: {
        select: {
          cluster: {
            select: {
              site: {
                select: {
                  workspace: { select: { organizationId: true } },
                },
              },
            },
          },
          finding: {
            select: {
              site: {
                select: {
                  workspace: { select: { organizationId: true } },
                },
              },
            },
          },
        },
      },
    },
  });

  if (!task) {
    redirect("/reviews?review_error=not_found");
  }

  const orgId =
    task.suggestion?.cluster?.site.workspace.organizationId ??
    task.suggestion?.finding?.site.workspace.organizationId;

  if (!orgId) {
    redirect("/reviews?review_error=no_org");
  }

  const membership = await prisma.membership.findFirst({
    where: { userId: user.id, organizationId: orgId },
    select: { role: true },
  });

  if (!membership) {
    redirect("/reviews?review_error=forbidden");
  }

  if (!hasPermission(membership.role, "review:manage")) {
    redirect("/reviews?review_error=forbidden");
  }

  try {
    await prisma.reviewTask.update({
      where: { id: taskId },
      data: {
        status: reviewStatus,
        assigneeId: user.id,
        reviewedAt:
          reviewStatus === "APPROVED" || reviewStatus === "REJECTED"
            ? new Date()
            : undefined,
      },
    });
  } catch {
    redirect("/reviews?review_error=update_failed");
  }

  revalidatePath("/reviews");
}

import { requireSession } from "@/lib/session";
import { prisma } from "@/lib/db";
import type { Prisma } from "@aros/db";
import Link from "next/link";
import { updateReviewAction } from "./actions";
import { getRoutePlatformTruth } from "@/lib/platform-truth-cache";
import { resolveDashboardOrgMembership } from "@/lib/route-data-boundary";
import { RouteReliabilityNotice } from "@/components/reliability/route-reliability-notice";
import { hasPermission } from "@aros/config";
import { StatusBadge } from "@aros/ui";

export const metadata = { title: "Reviews - AROS" };

export default async function ReviewsPage({
  searchParams,
}: {
  searchParams: Promise<{ review_error?: string }>;
}) {
  const user = await requireSession();
  const platformTruth = await getRoutePlatformTruth();
  const params = await searchParams;
  const canViewSystem = await prisma.membership
    .findMany({ where: { userId: user.id }, select: { role: true } })
    .then((rows) => rows.some((m) => hasPermission(m.role, "org:system:view")))
    .catch(() => false);

  const reviewError = params.review_error
    ? ({
        missing_task: "Review task not specified.",
        invalid_status: "Invalid review status.",
        not_found: "Review task not found.",
        no_org: "Could not determine organization for this review.",
        forbidden: "You do not have permission to update this review.",
        update_failed: "Failed to update review. Please try again.",
      }[params.review_error] ?? "An error occurred.")
    : null;

  const orgRes = await resolveDashboardOrgMembership(user.id, platformTruth);

  if (orgRes.kind === "platform_blocked") {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold text-slate-900">Review Queue</h1>
        <RouteReliabilityNotice
          variant="error"
          title="Reviews require a working database"
          showSystemLink={canViewSystem}
        >
          <p>
            The review queue cannot be loaded until core data services are
            healthy.
          </p>
        </RouteReliabilityNotice>
      </div>
    );
  }

  if (orgRes.kind === "error") {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold text-slate-900">Review Queue</h1>
        <RouteReliabilityNotice
          variant="error"
          title="Could not verify organization"
          showSystemLink={canViewSystem}
        >
          <p>{orgRes.message}</p>
        </RouteReliabilityNotice>
      </div>
    );
  }

  if (orgRes.kind === "none") {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold text-slate-900">Review Queue</h1>
        <RouteReliabilityNotice
          variant="info"
          title="No organization membership"
        >
          <p>You need an organization to view review tasks.</p>
        </RouteReliabilityNotice>
      </div>
    );
  }

  const reviewListInclude = {
    assignee: { select: { name: true, email: true } },
    suggestion: {
      select: { type: true, originalCode: true, suggestedCode: true },
    },
    _count: { select: { evidence: true } },
  } satisfies Prisma.ReviewTaskInclude;

  type ReviewListRow = Prisma.ReviewTaskGetPayload<{
    include: typeof reviewListInclude;
  }>;

  let tasks: ReviewListRow[] = [];
  let loadError: string | null = null;
  try {
    tasks = await prisma.reviewTask.findMany({
      where: {
        suggestion: {
          OR: [
            {
              finding: {
                site: { workspace: { organizationId: orgRes.organizationId } },
              },
            },
            {
              cluster: {
                site: { workspace: { organizationId: orgRes.organizationId } },
              },
            },
          ],
        },
      },
      orderBy: [{ status: "asc" }, { createdAt: "desc" }],
      include: reviewListInclude,
      take: 50,
    });
  } catch (e) {
    loadError = e instanceof Error ? e.message : "Database error";
    console.error("[reviews] query failed", e);
  }

  if (loadError) {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold text-slate-900">Review Queue</h1>
        <RouteReliabilityNotice
          variant="error"
          title="Review queue unavailable"
          showSystemLink={canViewSystem}
        >
          <p>Could not load review tasks ({loadError}).</p>
        </RouteReliabilityNotice>
      </div>
    );
  }

  const pendingCount = tasks.filter((t) => t.status === "PENDING").length;
  const inProgressCount = tasks.filter(
    (t) => t.status === "IN_PROGRESS",
  ).length;

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-slate-900">Review Queue</h1>
        <p className="text-slate-500 mt-1">
          {pendingCount} pending, {inProgressCount} in progress
        </p>
      </div>

      <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 text-sm text-blue-800">
        Some accessibility criteria cannot be verified by automated scanning
        alone. These tasks require human review for accurate conformance
        assessment.
      </div>

      {reviewError && (
        <RouteReliabilityNotice variant="error" title="Review update failed">
          <p>{reviewError}</p>
        </RouteReliabilityNotice>
      )}

      {tasks.length === 0 ? (
        <div className="card text-center py-12">
          <p className="text-slate-500">No review tasks yet.</p>
        </div>
      ) : (
        <div className="space-y-3">
          {tasks.map((task) => (
            <div key={task.id} className="card">
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <ReviewStatusBadge status={task.status} />
                    <span className="badge bg-slate-100 text-slate-700">
                      {task.type.toLowerCase().replace("_", " ")}
                    </span>
                  </div>
                  <h3 className="text-sm font-semibold text-slate-900">
                    {task.title}
                  </h3>
                  {task.description && (
                    <p className="text-sm text-slate-500 mt-1">
                      {task.description}
                    </p>
                  )}
                  <div className="flex items-center gap-4 mt-2 text-xs text-slate-400">
                    {task.assignee && (
                      <span>
                        Assigned to: {task.assignee.name ?? task.assignee.email}
                      </span>
                    )}
                    <span>{task._count.evidence} evidence artifacts</span>
                    <span>Created: {task.createdAt.toLocaleDateString()}</span>
                  </div>
                </div>
                <div className="flex gap-2">
                  {task.status === "PENDING" && (
                    <form action={updateReviewAction}>
                      <input type="hidden" name="taskId" value={task.id} />
                      <input type="hidden" name="status" value="IN_PROGRESS" />
                      <button type="submit" className="btn-secondary text-xs">
                        Start Review
                      </button>
                    </form>
                  )}
                  {task.status === "IN_PROGRESS" && (
                    <>
                      <form action={updateReviewAction}>
                        <input type="hidden" name="taskId" value={task.id} />
                        <input type="hidden" name="status" value="APPROVED" />
                        <button type="submit" className="btn-primary text-xs">
                          Approve
                        </button>
                      </form>
                      <form action={updateReviewAction}>
                        <input type="hidden" name="taskId" value={task.id} />
                        <input type="hidden" name="status" value="REJECTED" />
                        <button type="submit" className="btn-danger text-xs">
                          Reject
                        </button>
                      </form>
                    </>
                  )}
                  {task.suggestion && task.suggestionId && (
                    <Link
                      href={`/remediation/${task.suggestionId}`}
                      className="btn-ghost text-xs"
                    >
                      View Suggestion
                    </Link>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

