function formatIsoDateTime(value: string) {
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return value;
  }

  return new Intl.DateTimeFormat('en-CA', {
    dateStyle: 'medium',
    timeStyle: 'short',
  }).format(parsed);
}

import { NextResponse } from "next/server";
import { requireSession } from "@/lib/session";
import { prisma } from "@/lib/db";
import { hasPermission } from "@aros/config";
import type { MemberRole } from "@aros/db";
import { buildFindingsOperationalSummary } from "@/lib/findings/reporting-summary";
import { getRoutePlatformTruth } from "@/lib/platform-truth-cache";
import { resolveDashboardOrgMembership } from "@/lib/route-data-boundary";

export async function GET(request: Request) {
  try {
    const user = await requireSession();
    const { searchParams } = new URL(request.url);
    const requestedOrgId = searchParams.get("organizationId");
    const truth = await getRoutePlatformTruth();

    if (!truth.allowOrgScopedDbReads) {
      return NextResponse.json(
        {
          error: "degraded",
          message:
            "Operational summary unavailable while database or session store is unhealthy.",
          userImpactSummary: truth.userImpactSummary,
        },
        { status: 503 },
      );
    }

    let resolvedMembership: { organizationId: string; role: MemberRole } | null =
      null;

    if (requestedOrgId) {
      resolvedMembership = await prisma.membership.findUnique({
          where: {
            userId_organizationId: {
              userId: user.id,
              organizationId: requestedOrgId,
            },
          },
          select: { organizationId: true, role: true },
        });
    } else {
      const membership = await resolveDashboardOrgMembership(user.id, truth);

      if (membership.kind === "error") {
        return NextResponse.json(
          { error: "Membership lookup failed", message: membership.message },
          { status: 500 },
        );
      }

      if (membership.kind === "none" || membership.kind === "platform_blocked") {
        return NextResponse.json({ error: "Not found" }, { status: 404 });
      }

      resolvedMembership = {
        organizationId: membership.organizationId,
        role: membership.role,
      };
    }

    if (!resolvedMembership) {
      return NextResponse.json({ error: "Not found" }, { status: 404 });
    }

    if (!hasPermission(resolvedMembership.role, "reports:view")) {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    const summary = await buildFindingsOperationalSummary(
      prisma,
      resolvedMembership.organizationId,
      truth.flags.jobPipelinesHealthy,
    );

    return NextResponse.json({
      summary,
      platform: {
        jobPipelinesHealthy: truth.flags.jobPipelinesHealthy,
        workerRunning: truth.flags.workerRunning,
        optionalSubsystemIssues: truth.optionalSubsystemIssues,
      },
    });
  } catch (e) {
    if (e instanceof Error && e.message === "UNAUTHORIZED") {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
    console.error("[api/findings/summary]", e);
    return NextResponse.json(
      { error: "Failed to build summary" },
      { status: 500 },
    );
  }
}

import { NextResponse } from 'next/server';
import { collectPlatformHealth, toPublicHealthSummary } from '@aros/core-services';
// eslint-disable-next-line no-restricted-syntax
import { prisma } from '@/lib/db';

export const dynamic = 'force-dynamic';

/**
 * Liveness + coarse readiness for load balancers. No authentication; no secrets or env keys.
 */
export async function GET() {
  try {
    const report = await collectPlatformHealth(prisma);
    const summary = toPublicHealthSummary(report);
    const status = summary.ready ? 200 : 503;
    return NextResponse.json(summary, { status });
  } catch (e) {
    console.error('[health] collection failed:', e);
    return NextResponse.json(
      {
        checkedAt: new Date().toISOString(),
        live: true,
        installed: false,
        readiness: 'blocked',
        ready: false,
        checks: { database: false, redis: false, session: false },
        error: 'health_collection_failed',
      },
      { status: 503 }
    );
  }
}

import { NextResponse } from "next/server";
import { requireSession } from "@/lib/session";
import { prisma } from "@/lib/db";
import { hasPermission } from "@aros/config";
import {
  collectPlatformHealth,
  buildRoutePlatformTruth,
} from "@aros/core-services";

export async function GET(request: Request) {
  try {
    const user = await requireSession();
    const { searchParams } = new URL(request.url);
    const siteId = searchParams.get("siteId");
    const format = searchParams.get("format") ?? "json";

    const requestedOrgId = searchParams.get("organizationId");
    const membership = await prisma.membership.findFirst({
      where: {
        userId: user.id,
        ...(requestedOrgId ? { organizationId: requestedOrgId } : {}),
      },
      select: { organizationId: true, role: true },
    });
    if (!membership) {
      return NextResponse.json({ error: "Not found" }, { status: 404 });
    }
    if (!hasPermission(membership.role, "reports:export")) {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    const where: Record<string, unknown> = {
      occurrences: {
        some: {
          page: {
            site: {
              workspace: { organizationId: membership.organizationId },
              ...(siteId ? { id: siteId } : {}),
            },
          },
        },
      },
    };

    const health = await collectPlatformHealth(prisma);
    const truth = buildRoutePlatformTruth(health);

    const findings = await prisma.canonicalFinding.findMany({
      where,
      include: {
        occurrences: {
          include: { page: { select: { url: true, title: true } } },
          take: 100,
        },
      },
      orderBy: [{ impact: "asc" }, { occurrenceCount: "desc" }],
    });

    const report = {
      generatedAt: new Date().toISOString(),
      generatedBy: user.email,
      disclaimer:
        "This report provides evidence of accessibility testing and operator workflow. It does not constitute a guarantee of WCAG conformance.",
      platformTruth: {
        jobPipelinesHealthy: truth.flags.jobPipelinesHealthy,
        workerRunning: truth.flags.workerRunning,
        optionalSubsystemIssues: truth.optionalSubsystemIssues,
      },
      summary: {
        totalFindings: findings.length,
        bySeverity: {
          critical: findings.filter((f) => f.impact === "CRITICAL").length,
          serious: findings.filter((f) => f.impact === "SERIOUS").length,
          moderate: findings.filter((f) => f.impact === "MODERATE").length,
          minor: findings.filter((f) => f.impact === "MINOR").length,
        },
        byEvidenceSource: {
          automatedAxe: findings.filter(
            (f) => f.evidenceSource === "AUTOMATED_AXE",
          ).length,
          manualReview: findings.filter(
            (f) => f.evidenceSource === "MANUAL_REVIEW",
          ).length,
          imported: findings.filter((f) => f.evidenceSource === "IMPORTED")
            .length,
        },
      },
      findings: findings.map((f) => ({
        id: f.id,
        ruleId: f.ruleId,
        impact: f.impact,
        status: f.status,
        evidenceSource: f.evidenceSource,
        description: f.description,
        wcagTags: f.wcagTags,
        occurrenceCount: f.occurrenceCount,
        firstSeenAt: f.firstSeenAt,
        lastSeenAt: f.lastSeenAt,
        lastVerifiedAt: f.lastVerifiedAt,
        lastScanRunId: f.lastScanRunId,
        reopenedCount: f.reopenedCount,
        affectedPages: f.occurrences.map((o) => ({
          url: o.page.url,
          title: o.page.title,
          selector: o.selector,
        })),
      })),
    };

    if (format === "csv") {
      const lines = ["Rule ID,Impact,Status,Description,Occurrences,WCAG Tags"];
      for (const f of report.findings) {
        lines.push(
          `"${f.ruleId}","${f.impact}","${f.status}","${f.description.replace(/"/g, '""')}",${f.occurrenceCount},"${f.wcagTags.join("; ")}"`,
        );
      }
      return new NextResponse(lines.join("\n"), {
        headers: {
          "Content-Type": "text/csv",
          "Content-Disposition": `attachment; filename="aros-report-${new Date().toISOString().split("T")[0]}.csv"`,
        },
      });
    }

    return NextResponse.json(report, {
      headers: {
        "Content-Disposition": `attachment; filename="aros-report-${new Date().toISOString().split("T")[0]}.json"`,
      },
    });
  } catch (error) {
    if (error instanceof Error && error.message === "UNAUTHORIZED") {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
    console.error("Report generation error:", error);
    return NextResponse.json(
      { error: "Failed to generate report" },
      { status: 500 },
    );
  }
}

